import{_ as a,o as t,c as n,a3 as i}from"./chunks/framework.BZKbe9n2.js";const f=JSON.parse('{"title":"Maintenance","description":"","frontmatter":{},"headers":[],"relativePath":"administration/maintenance.md","filePath":"administration/maintenance.md"}'),r={name:"administration/maintenance.md"};function o(s,e,l,c,d,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance&quot;">​</a></h1><h2 id="system-maintenance" tabindex="-1">System maintenance <a class="header-anchor" href="#system-maintenance" aria-label="Permalink to &quot;System maintenance&quot;">​</a></h2><p>The system maintenance (<strong>Settings</strong>, admins) runs by default daily at 03:00 in the installation&#39;s time zone; admins can change the schedule (off, daily, weekly), the grace period and the safety limit, or choose to only report. It:</p><ul><li>deletes orphaned files and leftovers of interrupted transfers in the library&#39;s managed folder, after a grace period (default 24 hours);</li><li>lists managed originals whose file is missing (it never changes them).</li></ul><p>Referenced files are never touched. If a run would delete more than the safety limit (default 1 % of the managed files, at least 10), it deletes nothing and waits for your confirmation – this protects against a database restored from an older backup or a wrong library mount.</p><h2 id="identification-and-metadata" tabindex="-1">Identification and metadata <a class="header-anchor" href="#identification-and-metadata" aria-label="Permalink to &quot;Identification and metadata&quot;">​</a></h2><p>After every import, Anthology identifies the recordings: by ISRC, by audio fingerprint at AcoustID (with an API key), else by searching MusicBrainz for artist and title. Matches below certainty go to the review list. A daily refresh compares identified recordings with MusicBrainz; changes to values someone set by hand become conflicts.</p><h2 id="quality-check" tabindex="-1">Quality check <a class="header-anchor" href="#quality-check" aria-label="Permalink to &quot;Quality check&quot;">​</a></h2><p>Editors and admins can start the quality check of the whole library in <strong>Settings</strong>. It analyses the spectrum of every file once and stores its <strong>effective quality</strong>. Imports and orders analyse only the files they need to compare.</p><h2 id="covers" tabindex="-1">Covers <a class="header-anchor" href="#covers" aria-label="Permalink to &quot;Covers&quot;">​</a></h2><p>Covers are fetched after every import (embedded images, the Cover Art Archive). Once per installation, a job fetches them for the existing library. Editors can fetch them again for one album or the whole library.</p><h2 id="jobs" tabindex="-1">Jobs <a class="header-anchor" href="#jobs" aria-label="Permalink to &quot;Jobs&quot;">​</a></h2><p>Every long task is a job. The job overview shows them with live progress; you can pause, resume or cancel them. <code>ANTHOLOGY_JOBS_THROTTLE</code> limits how many run at once.</p>',13)])])}const u=a(r,[["render",o]]);export{f as __pageData,u as default};
